// TensorRT for RTX: compiled once per SDK version (TRT_RTX_MINOR = 7, 8, ...), each copy against that version's
// headers (trt_rtx_sdk.h, generated by CMake, names them by absolute path). The SDK reuses the full TensorRT's header
// names, its nvinfer1 namespace and its entry-point names, so here they're renamed (nvinfer1 -> nvinfer1_rtx8) and the
// DLL's entry points are taken with GetProcAddress (trt_loader keeps it loaded), never linked: no symbol is shared
// with the full TensorRT or with another version's copy.
#include "trt_rtx_sdk.h"

#define RTX_CAT2(a, b) a##_rtx##b
#define RTX_CAT(a, b) RTX_CAT2(a, b)
#define nvinfer1 RTX_CAT(nvinfer1, TRT_RTX_MINOR)
#define nvonnxparser RTX_CAT(nvonnxparser, TRT_RTX_MINOR)
#include TRT_RTX_NVINFER
#include TRT_RTX_ONNXPARSER

#include "rtx_backend.h"

static_assert(NV_TENSORRT_MAJOR == 1 && NV_TENSORRT_MINOR == TRT_RTX_MINOR, "headers of another TensorRT for RTX version");

int RTX_CAT(trt_rtx_header_version, TRT_RTX_MINOR)() { return NV_TENSORRT_VERSION; }
